"""Domain schemas.

Two kinds of claims are kept strictly apart:

* ``Evidence`` — a verbatim span of extracted page text, located by document,
  page and character offsets. Never produced by a model.
* ``Inference`` — a statement generated by a model. It must cite at least one
  ``Evidence`` and records which model produced it.

Validation here is structural: IDs match content and every reference
resolves inside a report. Whether a cited quote really exists in the source is
checked separately (``app.services.evidence``). Whether it semantically
supports the claim citing it is not checked anywhere yet.

IDs are deterministic (see ``app.core.ids``). Each model derives its expected
ID from its own content: an omitted ID is filled in, a mismatching one is
rejected, so callers cannot attach a fabricated identifier to a record.

Models are mutable and pydantic does not re-validate on attribute assignment
or list mutation. Anything leaving the backend must go through
``app.services.report.finalize_report``, which re-validates a serialized
snapshot and returns an immutable ``FinalizedReport``.
"""

from collections.abc import Mapping
from datetime import date, datetime
from enum import StrEnum
from types import MappingProxyType
from typing import Annotated, Literal, Self

from pydantic import BaseModel, ConfigDict, Field, HttpUrl, field_serializer, field_validator, model_validator

from app.core import ids

DocumentId = Annotated[str, Field(pattern=ids.DOCUMENT_ID_PATTERN)]
Sha256Hex = Annotated[str, Field(pattern=r"^[0-9a-f]{64}$")]


class _Schema(BaseModel):
    model_config = ConfigDict(extra="forbid", str_strip_whitespace=False)

    def _bind_id(self, field: str, expected: str) -> None:
        current = getattr(self, field)
        if not current:
            object.__setattr__(self, field, expected)
        elif current != expected:
            raise ValueError(f"{field} {current!r} does not match content-derived id {expected!r}")


class Document(_Schema):
    document_id: str = ""
    sha256: Sha256Hex
    filename: str = Field(min_length=1)
    title: str | None = None
    page_count: int = Field(ge=1)
    issuer: str = "Banque Centrale de Tunisie"
    reference: str | None = Field(default=None, description="Official reference, e.g. 'Circulaire n°2018-06'.")
    publication_date: date | None = None
    source_url: HttpUrl | None = None

    @model_validator(mode="after")
    def _check_id(self) -> Self:
        self._bind_id("document_id", ids.document_id(self.sha256))
        return self


class ExtractedPage(_Schema):
    """Raw text of one PDF page. Evidence offsets index into ``text``."""

    page_id: str = ""
    document_id: DocumentId
    page_number: int = Field(ge=1, description="1-based physical page number in the PDF.")
    text: str

    @property
    def has_text(self) -> bool:
        return bool(self.text.strip())

    @model_validator(mode="after")
    def _check_id(self) -> Self:
        self._bind_id("page_id", ids.page_id(self.document_id, self.page_number))
        return self


def page_text_digest(document_sha256: str, pages: list[ExtractedPage]) -> str:
    """SHA-256 over canonical JSON of the source hash and every (page_number, text)."""
    return ids.content_digest(
        {"document_sha256": document_sha256, "pages": [[p.page_number, p.text] for p in pages]}
    )


class ExtractionProvenance(_Schema):
    """How the page text of an ``ExtractedDocument`` was produced.

    ``text_digest`` makes a stored extraction artifact tamper-evident and lets
    a re-extraction be compared byte-for-byte. It does NOT prove the text was
    derived from the PDF bytes: anyone can recompute a digest over altered
    text. Only re-running the recorded extractor on the source PDF does that.
    """

    extractor_name: str = Field(min_length=1)
    extractor_version: str = Field(min_length=1)
    extraction_mode: str = Field(min_length=1)
    text_digest: Sha256Hex


class ExtractedDocument(_Schema):
    document: Document
    provenance: ExtractionProvenance
    pages: list[ExtractedPage]

    @model_validator(mode="after")
    def _check_pages(self) -> Self:
        if [p.page_number for p in self.pages] != list(range(1, self.document.page_count + 1)):
            raise ValueError("pages must be numbered 1..page_count in order")
        if any(p.document_id != self.document.document_id for p in self.pages):
            raise ValueError("every page must belong to the document")
        if self.provenance.text_digest != page_text_digest(self.document.sha256, self.pages):
            raise ValueError("provenance.text_digest does not match page text")
        return self


class Evidence(_Schema):
    """A verified, verbatim quote: ``page.text[char_start:char_end] == quote``."""

    kind: Literal["verified_extract"] = "verified_extract"
    evidence_id: str = ""
    document_id: DocumentId
    page_number: int = Field(ge=1)
    char_start: int = Field(ge=0)
    char_end: int = Field(gt=0)
    quote: str = Field(min_length=1)

    @model_validator(mode="after")
    def _check(self) -> Self:
        if not self.quote.strip():
            raise ValueError("quote must contain non-whitespace text")
        if self.char_end - self.char_start != len(self.quote):
            raise ValueError("char_end - char_start must equal len(quote)")
        self._bind_id(
            "evidence_id",
            ids.stable_id("ev", self.document_id, self.page_number, self.char_start, self.char_end, self.quote),
        )
        return self


PROVISION_SEGMENT_SEPARATOR = "\n"
"""Joins the per-page segments of a multi-page provision in ``Provision.text``.

It is the only character not taken from the source: segment texts are copied
verbatim and the separator appears exactly once between consecutive segments.
"""


class ProvisionSegment(_Schema):
    """The part of a provision on one page: ``page.text[char_start:char_end]``."""

    page_number: int = Field(ge=1)
    char_start: int = Field(ge=0)
    char_end: int = Field(gt=0)

    @model_validator(mode="after")
    def _check(self) -> Self:
        if self.char_end <= self.char_start:
            raise ValueError("char_end must be > char_start")
        return self


class Provision(_Schema):
    """A provision identified by where it is in the source, not by its label.

    Identity is ``(document_id, segments)``. ``label`` (the heading as printed)
    and ``number`` (a normalised designation used to resolve references) are
    display attributes, so repeated labels never collide. ``text`` must equal
    the segment texts joined by ``PROVISION_SEGMENT_SEPARATOR``; checking that
    against the source pages is ``app.services.provisions.verify_provision``.

    ``parent_provision_id`` records nesting (an annex's own articles, a quoted
    provision inside an amending article). ``quoted`` marks text quoted from
    another instrument, which is not a provision of this document.
    """

    provision_id: str = ""
    document_id: DocumentId
    kind: Literal["preamble", "article", "annex", "heading"]
    label: str = Field(min_length=1, description="Heading as printed, e.g. 'Article 5 :'.")
    number: str | None = Field(default=None, description="Normalised designation, e.g. '1' for 'Article premier'.")
    segments: list[ProvisionSegment] = Field(min_length=1)
    text: str = Field(min_length=1)
    quoted: bool = False
    parent_provision_id: str | None = None

    @property
    def page_start(self) -> int:
        return self.segments[0].page_number

    @property
    def page_end(self) -> int:
        return self.segments[-1].page_number

    @model_validator(mode="after")
    def _check(self) -> Self:
        pages = [s.page_number for s in self.segments]
        if pages != list(range(pages[0], pages[0] + len(pages))):
            raise ValueError("segments must be on consecutive pages, one segment per page, in order")
        expected_len = sum(s.char_end - s.char_start for s in self.segments) + len(PROVISION_SEGMENT_SEPARATOR) * (
            len(self.segments) - 1
        )
        if len(self.text) != expected_len:
            raise ValueError("text length does not match segments")
        spans = [[s.page_number, s.char_start, s.char_end] for s in self.segments]
        self._bind_id("provision_id", ids.stable_id("prov", self.document_id, spans))
        if self.parent_provision_id == self.provision_id:
            raise ValueError("a provision cannot be its own parent")
        return self


class Inference(_Schema):
    """A model-generated statement. Never treated as evidence."""

    kind: Literal["model_inference"] = "model_inference"
    inference_id: str = ""
    statement: str = Field(min_length=1)
    model_id: str = Field(min_length=1, description="Identifier of the model that produced the statement.")
    supporting_evidence_ids: list[str] = Field(min_length=1)

    @model_validator(mode="after")
    def _check(self) -> Self:
        _unique(self.supporting_evidence_ids, "supporting_evidence_ids")
        self._bind_id(
            "inference_id",
            ids.stable_id("inf", self.model_id, self.statement, sorted(self.supporting_evidence_ids)),
        )
        return self


class RelationType(StrEnum):
    AMENDS = "amends"
    REPEALS = "repeals"
    SUPERSEDES = "supersedes"
    REFERENCES = "references"
    IMPLEMENTS = "implements"
    CONFLICTS_WITH = "conflicts_with"


class LexicalMatch(_Schema):
    """Where a cited quote names the relationship's target, and by which rule.

    Lexical only: it shows the target is *mentioned*, not that the passage
    establishes the relationship. ``app.services.relationships`` re-derives
    the pattern from the target and re-checks the match at finalization.
    """

    rule: Literal["regulagraph.lexical.v1"] = "regulagraph.lexical.v1"
    evidence_id: str
    match_start: int = Field(ge=0, description="Offset into the evidence quote.")
    match_end: int = Field(gt=0)


class RegulatoryRelationship(_Schema):
    """A directed relation from a provision to a provision or a whole document.

    The target is exactly one of ``target_provision_id`` and
    ``target_document_id`` (e.g. "this circular repeals circular 2018-16").

    ``basis="extracted"``: stated explicitly in the source text; requires a
    ``lexical_match`` showing the source-side quote names the target.
    ``basis="inferred"``: proposed by a model; must reference an ``Inference``.
    Both must cite evidence located inside the source or target provision, with
    at least one item inside the source (checked at finalization, see
    ``app.services.relationships``). Semantic support is never checked.

    ``status`` is fail-closed. ``"candidate"`` (the default) means "proposed,
    not confirmed" and is the only status ``finalize_report`` publishes today.
    ``"confirmed"`` is reserved for extracted relationships that pass
    confirmation checks which do not exist yet, so finalization rejects it.
    """

    relationship_id: str = ""
    source_provision_id: str
    target_provision_id: str | None = None
    target_document_id: DocumentId | None = None
    relation_type: RelationType
    basis: Literal["extracted", "inferred"]
    evidence_ids: list[str] = Field(min_length=1)
    inference_id: str | None = None
    lexical_match: LexicalMatch | None = None
    status: Literal["candidate", "confirmed"] = "candidate"

    @model_validator(mode="after")
    def _check(self) -> Self:
        if (self.target_provision_id is None) == (self.target_document_id is None):
            raise ValueError("exactly one of target_provision_id and target_document_id is required")
        if self.status == "confirmed" and self.basis != "extracted":
            raise ValueError("only extracted relationships can ever be confirmed")
        if self.source_provision_id == self.target_provision_id:
            raise ValueError("a provision cannot relate to itself")
        _unique(self.evidence_ids, "evidence_ids")
        if self.basis == "inferred" and self.inference_id is None:
            raise ValueError("inferred relationships must reference an inference_id")
        if self.basis == "extracted" and self.inference_id is not None:
            raise ValueError("extracted relationships must not reference an inference")
        if self.basis == "extracted" and self.lexical_match is None:
            raise ValueError("extracted relationships must record a lexical_match")
        if self.lexical_match is not None and self.lexical_match.evidence_id not in self.evidence_ids:
            raise ValueError("lexical_match must cite one of the relationship's evidence_ids")
        target = (
            ["provision", self.target_provision_id]
            if self.target_provision_id is not None
            else ["document", self.target_document_id]
        )
        self._bind_id(
            "relationship_id",
            ids.stable_id("rel", self.source_provision_id, self.relation_type.value, target),
        )
        return self

    @property
    def target_id(self) -> str:
        return self.target_provision_id or self.target_document_id  # type: ignore[return-value]


class InvestigationReport(_Schema):
    """Self-contained report: every referenced ID must resolve inside the report.

    Referential integrity only: this does not check quote text against sources
    (see ``verify_report_evidence``) or that evidence supports what cites it.

    ``report_id`` identifies the investigation *run* (question, time, documents).
    It deliberately does not cover findings: runs with the same inputs but
    different findings share a ``report_id``. Content is bound separately by
    ``content_digest()`` and ``FinalizedReport.content_digest``.
    """

    report_id: str = ""
    question: str = Field(min_length=1)
    generated_at: datetime
    document_ids: list[DocumentId] = Field(min_length=1)
    provisions: list[Provision] = Field(default_factory=list)
    evidence: list[Evidence] = Field(default_factory=list)
    inferences: list[Inference] = Field(default_factory=list)
    relationships: list[RegulatoryRelationship] = Field(default_factory=list)

    @model_validator(mode="after")
    def _check_references(self) -> Self:
        docs = _unique(self.document_ids, "document_ids")
        provs = _unique([p.provision_id for p in self.provisions], "provisions")
        evs = _unique([e.evidence_id for e in self.evidence], "evidence")
        infs = _unique([i.inference_id for i in self.inferences], "inferences")
        _unique([r.relationship_id for r in self.relationships], "relationships")

        for item in [*self.provisions, *self.evidence]:
            _require(item.document_id, docs, "document")
        by_id = {p.provision_id: p for p in self.provisions}
        for prov in self.provisions:
            if prov.parent_provision_id is not None:
                _require(prov.parent_provision_id, provs, "parent provision")
                if by_id[prov.parent_provision_id].document_id != prov.document_id:
                    raise ValueError("a provision's parent must be in the same document")
        for inf in self.inferences:
            for ev_id in inf.supporting_evidence_ids:
                _require(ev_id, evs, "evidence")
        for rel in self.relationships:
            _require(rel.source_provision_id, provs, "provision")
            if rel.target_provision_id is not None:
                _require(rel.target_provision_id, provs, "provision")
            else:
                _require(rel.target_document_id, docs, "document")  # type: ignore[arg-type]
            for ev_id in rel.evidence_ids:
                _require(ev_id, evs, "evidence")
            if rel.inference_id is not None:
                _require(rel.inference_id, infs, "inference")

        self._bind_id(
            "report_id",
            ids.stable_id("rep", self.question, self.generated_at.isoformat(), sorted(self.document_ids)),
        )
        return self

    def canonical_snapshot(self) -> str:
        """Canonical JSON of the entire report, findings included."""
        return ids.canonical_json(self.model_dump(mode="json"))

    def content_digest(self) -> str:
        """Full SHA-256 of ``canonical_snapshot()``; changes whenever any finding changes."""
        return ids.sha256_hex(self.canonical_snapshot().encode("utf-8"))


class FinalizedReport(_Schema):
    """Immutable, publishable snapshot produced by ``finalize_report``.

    The report is held as canonical JSON text, so it cannot be mutated in
    place; ``report()`` returns a freshly validated copy. Deserializing a
    ``FinalizedReport`` re-checks digest, canonical form and publication
    rules, but cannot re-verify evidence against sources: re-run
    ``finalize_report`` with the sources for that.
    """

    model_config = ConfigDict(extra="forbid", frozen=True)

    report_id: str
    content_digest: Sha256Hex
    snapshot: str
    verified_sources: Mapping[DocumentId, Sha256Hex] = Field(
        description="document_id -> provenance.text_digest of the extraction the evidence was verified against."
    )

    @field_validator("verified_sources", mode="after")
    @classmethod
    def _freeze_sources(cls, value: Mapping[str, str]) -> Mapping[str, str]:
        # frozen=True only blocks attribute assignment; a dict could still be edited in place.
        # Copy, so the caller's dict can't alias it, and expose a read-only view.
        return MappingProxyType(dict(sorted(value.items())))

    @field_serializer("verified_sources")
    def _dump_sources(self, value: Mapping[str, str]) -> dict[str, str]:
        return dict(value)  # a fresh copy; mutating it does not touch the model

    @model_validator(mode="after")
    def _check(self) -> Self:
        if ids.sha256_hex(self.snapshot.encode("utf-8")) != self.content_digest:
            raise ValueError("content_digest does not match snapshot")
        report = InvestigationReport.model_validate_json(self.snapshot)
        if report.canonical_snapshot() != self.snapshot:
            raise ValueError("snapshot is not in canonical form")
        if report.report_id != self.report_id:
            raise ValueError("report_id does not match snapshot")
        if set(report.document_ids) != set(self.verified_sources):
            raise ValueError("verified_sources must cover exactly the report's documents")
        assert_publishable(report)
        return self

    def report(self) -> InvestigationReport:
        return InvestigationReport.model_validate_json(self.snapshot)


def assert_publishable(report: InvestigationReport) -> None:
    """Fail closed: no relationship may be published as confirmed yet.

    Confirmation would require provision-span association (Sprint 2, R2) and
    further validation. None of it exists, so ``"confirmed"`` is always
    rejected. Semantic support is not verified for any status.
    """
    confirmed = [r.relationship_id for r in report.relationships if r.status == "confirmed"]
    if confirmed:
        raise ValueError(f"relationship confirmation checks are not implemented; cannot publish confirmed {confirmed}")


def _unique(values: list[str], name: str) -> set[str]:
    seen = set(values)
    if len(seen) != len(values):
        raise ValueError(f"duplicate ids in {name}")
    return seen


def _require(ref: str, known: set[str], kind: str) -> None:
    if ref not in known:
        raise ValueError(f"unresolved {kind} reference {ref!r}")
